  const link=`data:text/csv;charset=utf-8,${encodeURIComponent(template)}`;
  const sourceRowCount=new Set(plan?.items.filter(item=>item.source).map(item=>`${item.source?.sheet}:${item.line}`) ?? []).size;
  const reviewRows=plan?.items.filter(item=>item.source||item.after.catalogSource==='ODM'||!!item.after.odmCustomerSourceName) ?? [];
